    "My Registered Grievances & Service Submissions": "எனது புகார்கள் & சேவை விண்ணப்பங்கள்",
    "Access your submitted complaints, track real-time statutory SLA countdowns, and inspect verified officer redressal reports.": "உங்கள் புகார்களைக் காண்க, நேரடி SLA காலக்கெடுவை கண்காணிக்கவும், அதிகாரியின் அறிக்கையை சரிபார்க்கவும்.",
