    "Time-Bound Public Service Delivery Act (GIGW 3.0 Standard)": "காலவரையறைக்குட்பட்ட பொது சேவை விநியோகச் சட்டம் (GIGW 3.0)",
    "Every grievance is assigned a statutory SLA deadline. Breached cases auto-escalate directly to Senior Zonal Commissioners.": "ஒவ்வொரு புகார் மீதும் சட்டப்பூர்வ காலக்கெடு உண்டு. தவறும் பட்சத்தில் உயர் அதிகாரிகளுக்கு தானாக அனுப்பப்படும்.",
